# Regex to find paths: looks for C:\ ... .wav
paths = re.findall(r'[a-zA-Z]:\\[^\s]+\.wav', raw_text)

# Destination directory
dest_dir = Path(r"d:\GuviHCL_Hackathon\ai_voice_detection_api\training\data\ai")
dest_dir.mkdir(parents=True, exist_ok=True)

# Find start index
existing_files = list(dest_dir.glob("AISample_*.mpeg")) + list(dest_dir.glob("AISample_*.wav"))
indices = []
for f in existing_files:
    try:
        # File name format: AISample_XX.ext
        name = f.stem
        idx = int(name.split('_')[1])
        indices.append(idx)
    except:
        pass

start_idx = max(indices) + 1 if indices else 1

print(f"Found {len(paths)} files to import.")
print(f"Starting index: {start_idx}")

for i, src_path in enumerate(paths):
    current_idx = start_idx + i
    src = Path(src_path)
    
    # New filename
    new_name = f"AISample_{current_idx}{src.suffix}" # Keep .wav extension
    dest = dest_dir / new_name
    
    try:
        shutil.copy2(src, dest)
        print(f"Copied: {src.name} -> {new_name}")
    except Exception as e:
        print(f"Error copying {src}: {e}")

print("Import complete.")
